<?php
include_once('../config.php');
$pagegen=new page_gen();$pagegen->round_to=4;$pagegen->start();
$game=new Game();if(!$game->loggedIn){header('Location: ../index.php');exit;}
$db=$game->db_link;$uid=(int)($_SESSION['userid']??0);
function sab_h($v): string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sab_n($v): string{return number_format((int)$v);} function sab_one(mysqli $db,string $sql): ?array{$q=$db->query($sql);return $q?$q->fetch_assoc():null;}
function sab_install(mysqli $db): void{
 $db->query("CREATE TABLE IF NOT EXISTS sabotage_missions (mission_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,uid INT NOT NULL,target_uid INT NOT NULL,mission_type ENUM('power_blackout','weapons_disruption','shield_infiltration','production_strike','logistics_cut','defense_breach','command_intrusion') NOT NULL,status ENUM('queued','resolved','detected','failed','recovered','cancelled') NOT NULL DEFAULT 'queued',target_name VARCHAR(120) NOT NULL DEFAULT 'Unknown Target',infiltration_score INT NOT NULL DEFAULT 0,detection_risk INT NOT NULL DEFAULT 0,effect_strength INT NOT NULL DEFAULT 0,turns_cost INT NOT NULL DEFAULT 1,cooldown_seconds INT NOT NULL DEFAULT 3600,effect_until DATETIME NULL,resolved_at DATETIME NULL,report TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(mission_id),KEY idx_sabotage_uid(uid),KEY idx_sabotage_target(target_uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->query("CREATE TABLE IF NOT EXISTS sabotage_effects (effect_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,mission_id BIGINT UNSIGNED NOT NULL,target_uid INT NOT NULL,effect_type ENUM('power_blackout','weapons_disruption','shield_infiltration','production_strike','logistics_cut','defense_breach','command_intrusion') NOT NULL,magnitude INT NOT NULL DEFAULT 0,status ENUM('active','expired','purged') NOT NULL DEFAULT 'active',starts_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,ends_at DATETIME NOT NULL,PRIMARY KEY(effect_id),KEY idx_sabotage_effect_target(target_uid),KEY idx_sabotage_effect_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->query("CREATE TABLE IF NOT EXISTS counterintelligence_profiles (uid INT NOT NULL,alert_level INT NOT NULL DEFAULT 0,sensor_bonus INT NOT NULL DEFAULT 0,trace_bonus INT NOT NULL DEFAULT 0,last_breach_at DATETIME NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->query("CREATE TABLE IF NOT EXISTS sabotage_recovery_log (recovery_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,effect_id BIGINT UNSIGNED NOT NULL,target_uid INT NOT NULL,recovery_type ENUM('automatic','countermeasure','admin_purge') NOT NULL,restored_percent INT NOT NULL DEFAULT 100,recovered_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(recovery_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
}
sab_install($db);
$types=['power_blackout'=>'Power Blackout','weapons_disruption'=>'Weapons Disruption','shield_infiltration'=>'Shield Infiltration','production_strike'=>'Production Strike','logistics_cut'=>'Logistics Cut','defense_breach'=>'Defense Breach','command_intrusion'=>'Command Intrusion'];
$action=(string)($_GET['id']??'mainDisplay');$arg=(string)($_GET['atype']??'');$status='';$error='';
$stats=sab_one($db,"SELECT p.mil_cov,p.mil_anti,u.actionTurns FROM power p INNER JOIN userdata u ON u.uid=p.uid WHERE p.uid=$uid LIMIT 1")??['mil_cov'=>0,'mil_anti'=>0,'actionTurns'=>0];
if($action==='launch'){
 $parts=explode(':',$arg);$type=in_array(($parts[0]??''),array_keys($types),true)?$parts[0]:'power_blackout';$target=(int)($parts[1]??0);$targetRow=$target>0?sab_one($db,"SELECT u.uname,p.mil_cov,p.mil_anti FROM users u LEFT JOIN power p ON p.uid=u.uid WHERE u.uid=$target LIMIT 1"):null;
 if(!$targetRow||$target===$uid)$error='Choose a valid opposing target.';elseif((int)$stats['actionTurns']<1)$error='No action turns are available for a covert operation.';else{
  $cov=(int)$stats['mil_cov'];$anti=(int)($targetRow['mil_anti']??0);$profile=sab_one($db,"SELECT alert_level,sensor_bonus,trace_bonus FROM counterintelligence_profiles WHERE uid=$target");$alert=(int)($profile['alert_level']??0);$risk=max(5,min(95,35+(int)round($anti/3)-((int)round($cov/4))+(int)($profile['trace_bonus']??0)+$alert));$infiltration=max(1,$cov+random_int(0,100)-$anti);$chance=max(10,min(90,50+(int)round($infiltration/5)-(int)round($risk/3)));$success=random_int(1,100)<=$chance;$strength=max(10,min(90,(int)round(15+$cov/20)));$duration=['power_blackout'=>1800,'weapons_disruption'=>2400,'shield_infiltration'=>2400,'production_strike'=>3600,'logistics_cut'=>3000,'defense_breach'=>2700,'command_intrusion'=>1800][$type];$until=date('Y-m-d H:i:s',time()+$duration);$missionStatus=$success?'resolved':'detected';$report=$success?$types[$type].' succeeded against '.(string)$targetRow['uname'].'. Effect strength: '.$strength.'%.':$types[$type].' was detected by '.(string)$targetRow['uname'].'. Counterintelligence has been alerted.';$st=$db->prepare("INSERT INTO sabotage_missions (uid,target_uid,mission_type,target_name,status,infiltration_score,detection_risk,effect_strength,turns_cost,cooldown_seconds,effect_until,resolved_at,report) VALUES (?,?,?,?,?,?,?,?,1,3600,?,?,?)");if($st){$name=(string)$targetRow['uname'];$st->bind_param('iisssiiisss',$uid,$target,$type,$name,$missionStatus,$infiltration,$risk,$strength,$until,$until,$report);$st->execute();$mid=(int)$db->insert_id;}$db->query("UPDATE userdata SET actionTurns=GREATEST(0,actionTurns-1) WHERE uid=$uid LIMIT 1");if($success){$db->query("INSERT INTO sabotage_effects (mission_id,target_uid,effect_type,magnitude,ends_at) VALUES ($mid,$target,'$type',$strength,'$until')");$db->query("INSERT INTO counterintelligence_profiles (uid,alert_level,sensor_bonus,trace_bonus,last_breach_at) VALUES ($target,5,0,0,NOW()) ON DUPLICATE KEY UPDATE alert_level=LEAST(100,alert_level+5),last_breach_at=NOW()");$status='Sabotage successful. A temporary '.$types[$type].' effect is active.';}else{$db->query("INSERT INTO counterintelligence_profiles (uid,alert_level,sensor_bonus,trace_bonus,last_breach_at) VALUES ($target,20,0,5,NOW()) ON DUPLICATE KEY UPDATE alert_level=LEAST(100,alert_level+20),trace_bonus=trace_bonus+5,last_breach_at=NOW()");$status='Sabotage detected. The target counterintelligence profile has escalated.';}}
}
if($action==='purge'&&ctype_digit($arg)){$effect=(int)$arg;$row=sab_one($db,"SELECT effect_id,target_uid FROM sabotage_effects WHERE effect_id=$effect AND status='active' LIMIT 1");if(!$row||((int)$row['target_uid']!==$uid))$error='This effect cannot be purged from the current command profile.';else{$db->query("UPDATE sabotage_effects SET status='purged' WHERE effect_id=$effect");$db->query("INSERT INTO sabotage_recovery_log (effect_id,target_uid,recovery_type,restored_percent) VALUES ($effect,$uid,'countermeasure',100)");$status='Countermeasure deployed. The sabotage effect has been purged.';}}
$active=$db->query("SELECT effect_id,mission_id,effect_type,magnitude,ends_at FROM sabotage_effects WHERE target_uid=$uid AND status='active' AND ends_at>NOW() ORDER BY effect_id DESC");$mine=$db->query("SELECT mission_id,target_uid,target_name,mission_type,status,infiltration_score,detection_risk,effect_strength,report,created_at FROM sabotage_missions WHERE uid=$uid ORDER BY mission_id DESC LIMIT 20");$profile=sab_one($db,"SELECT alert_level,sensor_bonus,trace_bonus FROM counterintelligence_profiles WHERE uid=$uid");
?><div class="page-hub sabotage-console"><div class="page-hub-head"><span class="rts-kicker">STARGATE WARS // COVERT OPERATIONS</span><h3>Sabotage and Counterintelligence</h3><p>Disrupt hostile power, weapons, shields, production, logistics, defenses, or command systems while managing infiltration risk and detection.</p></div><?php if($status):?><div class="card rts-alert success"><strong><?=sab_h($status)?></strong></div><?php endif;?><?php if($error):?><div class="card rts-alert danger"><strong><?=sab_h($error)?></strong></div><?php endif;?><div class="rts-unit-grid"><section class="card"><h4>Covert Profile</h4><p>Infiltration power: <b><?=sab_n($stats['mil_cov'])?></b><br>Anti-covert defense: <b><?=sab_n($stats['mil_anti'])?></b><br>Action turns: <b><?=sab_n($stats['actionTurns'])?></b></p><h4>Counterintelligence</h4><p>Alert level: <b><?=sab_n($profile['alert_level']??0)?></b><br>Sensor bonus: <b><?=sab_n($profile['sensor_bonus']??0)?></b><br>Trace bonus: <b><?=sab_n($profile['trace_bonus']??0)?></b></p></section><section class="card"><h4>Launch Sabotage</h4><p>Target UID must identify an opposing player. The result is resolved through infiltration versus anti-covert defense, alert level, and trace risk.</p><form class="admin-form-grid" onsubmit="event.preventDefault();var t=this.type.value;var u=this.target.value;sendData('sabotage','get','launch',t+':'+u);return false"><label>Target UID<input type="number" name="target" min="1" required></label><label>Operation<select name="type"><?php foreach($types as $key=>$label):?><option value="<?=sab_h($key)?>"><?=sab_h($label)?></option><?php endforeach;?></select></label><button class="rts-primary">Launch Covert Operation</button></form></section></div><section class="card"><h4>Active Effects on Your Empire</h4><?php if($active&&$active->num_rows):?><table class="mini-table" width="100%"><tr><th>Effect</th><th>Magnitude</th><th>Ends</th><th>Recovery</th></tr><?php while($e=$active->fetch_assoc()):?><tr><td><?=sab_h($types[$e['effect_type']]??$e['effect_type'])?></td><td><?=sab_n($e['magnitude'])?>%</td><td><?=sab_h($e['ends_at'])?></td><td><a href="javascript:void(0)" onclick="sendData('sabotage','get','purge','<?=sab_n($e['effect_id'])?>');return false">Deploy Countermeasure</a></td></tr><?php endwhile;?></table><?php else:?><p>No active sabotage effects are affecting this empire.</p><?php endif;?></section><section class="card"><h4>Covert Mission Reports</h4><?php if($mine&&$mine->num_rows):?><div class="rts-report-list"><?php while($m=$mine->fetch_assoc()):?><article><b><?=sab_h($types[$m['mission_type']]??$m['mission_type'])?> against <?=sab_h($m['target_name'])?></b><span>Status: <?=sab_h($m['status'])?> · Infiltration <?=sab_n($m['infiltration_score'])?> · Detection risk <?=sab_n($m['detection_risk'])?> · Effect <?=sab_n($m['effect_strength'])?>%</span><p><?=sab_h($m['report'])?></p></article><?php endwhile;?></div><?php else:?><p>No sabotage missions have been recorded.</p><?php endif;?></section></div><?php $pagegen->stop();print('page generation time: '.$pagegen->gen()); ?>
